-- Kea-owned tables the flax migrations GRANT on / attach triggers to. In production Kea
-- creates them; for tests this is a FIXTURE with column shapes copied from live eindhoven
-- (information_schema, read-only). Not real Kea schema: no indexes beyond the primary keys,
-- except the hosts identifier+subnet unique index below, which flax's kea.hosts upsert
-- (flax_classify/kea_hosts.py _UPSERT_SQL, flax_control order reservations) names as its
-- ON CONFLICT arbiter; without it every upsert fails ("no unique or exclusion constraint
-- matching the ON CONFLICT specification").
-- conftest.py applies it between migration 001 (CREATE SCHEMA kea) and upgrade head.

CREATE TABLE kea.hosts (
    host_id integer NOT NULL,
    dhcp_identifier bytea NOT NULL,
    dhcp_identifier_type smallint NOT NULL,
    dhcp4_subnet_id bigint,
    dhcp6_subnet_id bigint,
    ipv4_address bigint,
    hostname character varying(255),
    dhcp4_client_classes character varying(255),
    dhcp6_client_classes character varying(255),
    dhcp4_next_server bigint,
    dhcp4_server_hostname character varying(64),
    dhcp4_boot_file_name character varying(128),
    user_context text,
    auth_key character varying(32)
);

ALTER TABLE kea.hosts ALTER COLUMN host_id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME kea.hosts_host_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE kea.ipv6_reservations (
    reservation_id integer NOT NULL,
    address inet NOT NULL,
    prefix_len smallint NOT NULL,
    type smallint NOT NULL,
    dhcp6_iaid integer,
    host_id integer NOT NULL
);

ALTER TABLE kea.ipv6_reservations ALTER COLUMN reservation_id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME kea.ipv6_reservations_reservation_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

CREATE TABLE kea.lease4 (
    address bigint NOT NULL,
    hwaddr bytea,
    client_id bytea,
    valid_lifetime bigint,
    expire timestamp with time zone,
    subnet_id bigint,
    fqdn_fwd boolean,
    fqdn_rev boolean,
    hostname character varying(255),
    state bigint,
    user_context text,
    relay_id bytea,
    remote_id bytea,
    pool_id bigint DEFAULT 0 NOT NULL
);

CREATE TABLE kea.lease6 (
    address inet NOT NULL,
    duid bytea,
    valid_lifetime bigint,
    expire timestamp with time zone,
    subnet_id bigint,
    pref_lifetime bigint,
    lease_type smallint,
    iaid integer,
    prefix_len smallint,
    fqdn_fwd boolean,
    fqdn_rev boolean,
    hostname character varying(255),
    state bigint,
    hwaddr bytea,
    hwtype smallint,
    hwaddr_source smallint,
    user_context text,
    pool_id bigint DEFAULT 0 NOT NULL
);

ALTER TABLE ONLY kea.hosts
    ADD CONSTRAINT hosts_pkey PRIMARY KEY (host_id);

-- Kea's per-subnet identifier uniqueness (partial: global reservations carry a NULL
-- subnet), in the predicate form the flax upsert's ON CONFLICT ... WHERE infers.
CREATE UNIQUE INDEX key_dhcp4_identifier_subnet_id ON kea.hosts
    (dhcp_identifier, dhcp_identifier_type, dhcp4_subnet_id)
    WHERE dhcp4_subnet_id IS NOT NULL;

ALTER TABLE ONLY kea.ipv6_reservations
    ADD CONSTRAINT ipv6_reservations_pkey PRIMARY KEY (reservation_id);

ALTER TABLE ONLY kea.lease4
    ADD CONSTRAINT lease4_pkey PRIMARY KEY (address);

ALTER TABLE ONLY kea.lease6
    ADD CONSTRAINT lease6_pkey PRIMARY KEY (address);




-- The DHCPv6 twin, as on live eindhoven (pg_indexes read 2026-11-11).
CREATE UNIQUE INDEX key_dhcp6_identifier_subnet_id ON kea.hosts
    (dhcp_identifier, dhcp_identifier_type, dhcp6_subnet_id)
    WHERE dhcp6_subnet_id IS NOT NULL;
